import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  label?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

function ArticleTagPicker({
  label = 'Теги статьи',
  defaultTags = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const unique: string[] = [];
    for (const tag of next) {
      const trimmed = tag.trim();
      if (trimmed && !unique.includes(trimmed)) unique.push(trimmed);
    }
    apply(unique);
  };

  const remove = (tag: string) => apply(tags.filter((item) => item !== tag));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <span className="jx-label" id="article-tags-label">
        {label}
      </span>

      <JxTagInput
        ariaLabel={label}
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={add}
      />

      {tags.length === 0 ? (
        <JxEmptyState
          title="Тегов пока нет"
          message="Введите слово в поле выше и нажмите Enter, чтобы добавить первый тег."
        />
      ) : (
        <div
          role="list"
          aria-labelledby="article-tags-label"
          style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}
        >
          {tags.map((tag) => (
            <JxChip
              key={tag}
              role="listitem"
              active
              removable
              onRemove={() => remove(tag)}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

export default ArticleTagPicker;

